// Exists checks whether an entity with the given ID exists.
func (s *Store) Exists(ctx context.Context, entity string, id string) (bool, error) {
	switch entity {
	case "User":
		var count int64
		if err := s.db.WithContext(ctx).Model(&User{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "Role":
		var count int64
		if err := s.db.WithContext(ctx).Model(&Role{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "ManagedCluster":
		var count int64
		if err := s.db.WithContext(ctx).Model(&ManagedCluster{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "GatewayRelease":
		var count int64
		if err := s.db.WithContext(ctx).Model(&GatewayRelease{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "ManagedDatabase":
		var count int64
		if err := s.db.WithContext(ctx).Model(&ManagedDatabase{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "Gateway":
		var count int64
		if err := s.db.WithContext(ctx).Model(&Gateway{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	case "RoleBinding":
		var count int64
		if err := s.db.WithContext(ctx).Model(&RoleBinding{}).Where("id = ?", id).Count(&count).Error; err != nil {
			return false, err
		}
		return count > 0, nil
	default:
		return false, fmt.Errorf("unknown entity: %s", entity)
	}
}

// isUniqueConstraintError checks whether a database error is a unique
// constraint violation (PostgreSQL error code 23505).
func isUniqueConstraintError(err error) bool {
	if err == nil {
		return false
	}
	errStr := err.Error()
	return strings.Contains(errStr, "duplicate key value violates unique constraint") ||
		strings.Contains(errStr, "SQLSTATE 23505") ||
		strings.Contains(errStr, "duplicated key not allowed")
}
